def resolve(path, cwd, links):
    # Start with the initial path being relative or absolute
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split remaining path into components
    components = remaining.split('/')
    link_count = 0

    i = 0
    while i < len(components):
        component = components[i]
        i += 1

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                # Move to parent directory
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append the component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[candidate]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = '/'
                remaining_target = target[1:]
            else:
                # Relative target - relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                remaining_target = target

            # Append remaining components to be processed after target
            target_components = remaining_target.split('/')
            components = target_components + components[i:]
            i = 0
        else:
            # Not a symlink, just update current
            current = candidate

    # Return result, removing trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current

